public async Task RenamePostAsync(BlogContext blogContext, int postId, string newTitle, CancellationToken cancellationToken)
{
    var postQuery = from post in blogContext.Posts
                    where post.Id == postId
                    select post;

    var matchingPost = await postQuery.FirstOrDefaultAsync(cancellationToken)
        ?? throw new KeyNotFoundException($"No post found with id {postId}.");

    matchingPost.Title = newTitle;

    await blogContext.SaveChangesAsync(cancellationToken);
}
```

